{
  "window_id": "w0001",
  "observed_failures": [
    {
      "filename": "034.jpg",
      "field": "date",
      "predicted": "2018-08-09",
      "symptom": "date_incorrect",
      "hypothesis": "Receipt date is 09/03/2018 (DD/MM/YYYY). Agent likely parsed it with MM/DD/YYYY convention yielding 2018-08-09 (interpreting 08 as month from a differently-ordered OCR fragment), or confused month and day. The current skill's DATE_PATTERNS tries '%Y-%m-%d' first, but when none of the regex patterns matches ISO form it falls back to '%d-%m-%Y' — however it may also previously have tried '%m-%d-%Y'-style interpretations. The actual failure indicates ambiguity resolution for DD/MM vs MM/DD is not enforced for Malaysian receipts."
    },
    {
      "filename": "074.jpg",
      "field": "total_amount",
      "predicted": "702.00",
      "symptom": "amount_incorrect",
      "hypothesis": "Receipt is Thai Delicious Restaurant with 'Grand Total : 92.80'. Prediction '702.00' bears no resemblance to any shown total; likely picked a different numeric token (perhaps '7.20' change concatenated with something, or an OCR hallucination of '92.80' misread, or picked a quantity/price elsewhere). Priority tier matching may have grabbed a line without a valid amount or the fallback 'last number on next line' consumed an unrelated digit sequence. Possibly also an OCR digit confusion merging two tokens."
    },
    {
      "filename": "077.jpg",
      "field": "total_amount",
      "predicted": "23.26",
      "symptom": "amount_incorrect_subtotal_or_pre_rounding_picked",
      "hypothesis": "Banh Mi Cafe shows 'Total (Inclusive of GST): 23.26', 'Rounding Adj: -0.01', 'TOTAL: 23.25'. Agent picked 23.26 (the pre-rounding Total line) instead of the final 'TOTAL: 23.25' line. The priority rules in current skill treat first match for a tier; both lines contain 'TOTAL', so the first-encountered 'Total (Inclusive of GST)' wins over the final bold 'TOTAL:'. Need rule to prefer the LAST occurrence within the lowest-priority generic TOTAL tier OR to recognize rounding-adjusted final total."
    },
    {
      "filename": "078.jpg",
      "field": "total_amount",
      "predicted": "",
      "symptom": "amount_null_but_oracle_expects_value",
      "hypothesis": "Thai Delicious Restaurant image (actually 078 is a different Thai Delicious receipt) — agent emitted empty string rather than null. Two problems: (a) extraction failed where oracle presumably has a value, and (b) the empty cell is stored as '' not as null/None. Current skill says to set to None but code or Excel write path may be converting None/NaN to empty string, which is still interpreted as a non-null but wrong value by the verifier. Also the extraction logic may have failed to find Grand Total due to OCR noise."
    }
  ],
  "root_causes": [
    {
      "id": "rc_total_priority_last_vs_first",
      "description": "When multiple lines in the same priority tier contain the keyword (e.g., 'Total (Inclusive of GST)' and final 'TOTAL:' after rounding adjustment), current image-ocr skill selects the FIRST match. Receipts typically print the final payable total LAST, after rounding adjustments. This causes systematic selection of pre-rounding totals.",
      "affected_fields": ["077.jpg total_amount", "potentially other receipts with Rounding Adj lines"],
      "skill_locations": ["image-ocr → 'Total Amount Extraction' → extract_total() loop; 'Critical Rules for Receipt Extraction' bullet on priority order"]
    },
    {
      "id": "rc_date_dd_mm_vs_mm_dd_disambiguation",
      "description": "Date patterns include both '%Y-%m-%d' (ISO) and '%d-%m-%Y' (DD/MM) but Malaysian/SE-Asian receipts almost always use DD/MM/YYYY. When OCR introduces noise or the agent iterates alternate formats, swapping of day/month can occur. The current skill lacks an explicit 'prefer DD/MM/YYYY for ambiguous slash-separated dates' rule, and lacks sanity checks like 'if day<=12 and month<=12, prefer locale default'.",
      "affected_fields": ["034.jpg date", "any receipt with ambiguous DD/MM date where both digits ≤ 12"],
      "skill_locations": ["image-ocr → 'Date Extraction (reformat to ISO YYYY-MM-DD)' → DATE_PATTERNS ordering and extract_date()"]
    },
    {
      "id": "rc_null_vs_empty_string_in_excel",
      "description": "Task requires null when extraction fails. The xlsx and image-ocr skills instruct to use Python None, but the delivered output for 078.jpg shows total_amount as empty string ''. This means either (a) code path writes '' instead of None, or (b) pandas/openpyxl converts None in a string-typed Series to '' at write-time. Current image-ocr snippet uses df['total_amount'].astype('object') which can still coerce None to NaN then to '' via Excel writer defaults. Skill lacks explicit guidance to write cells as truly empty via openpyxl None assignment or to leave DataFrame cells as pd.NA / None without astype coercion.",
      "affected_fields": ["078.jpg total_amount"],
      "skill_locations": ["image-ocr → 'Batch Pipeline for Tabular Output' process_receipts(); xlsx → sections on writing data via pandas"]
    },
    {
      "id": "rc_total_extraction_hallucination_or_wrong_line",
      "description": "For 074.jpg (Grand Total 92.80), the predicted 702.00 suggests the extractor consumed a token from an unrelated line, possibly a concatenation of '7.20' + '0.00' or a quantity. The current regex `NUM_RE` greedily matches any number, and 'last number on line' can trap on misaligned OCR output where columns collapse. There is no sanity check comparing extracted total against item subtotals or rejecting values that aren't preceded by currency/decimal patterns.",
      "affected_fields": ["074.jpg total_amount"],
      "skill_locations": ["image-ocr → NUM_RE regex and extract_last_number(); extract_total() tier search"]
    },
    {
      "id": "rc_single_pass_ocr_insufficient_for_hard_receipts",
      "description": "The source agent relied on a single preprocessing + '--psm 6' pass with multi_pass_ocr only as a fallback when text was empty. Difficult receipts (faded, perforated, rotated) can produce partially correct text where only some fields are extractable; multi-pass combination should be the DEFAULT for receipts, with per-pass extraction and voting across passes rather than text concatenation.",
      "affected_fields": ["034.jpg date", "074.jpg total_amount", "078.jpg total_amount"],
      "skill_locations": ["image-ocr → 'Batch Pipeline for Tabular Output' and 'Multi-Pass OCR Strategy'"]
    }
  ],
  "skill_defects": [
    {
      "skill": "image-ocr",
      "defect": "extract_total() picks FIRST matching line within a tier; needs to prefer LAST occurrence for the generic TOTAL tier (which includes rounding-adjusted final totals) and ignore lines qualified with parenthetical descriptors like '(Inclusive of GST)', '(Excluding GST)' when a plain final 'TOTAL:' line exists later."
    },
    {
      "skill": "image-ocr",
      "defect": "DATE_PATTERNS lacks explicit prioritization for Malaysian/SE-Asian DD/MM/YYYY convention; ambiguous dates (day and month both ≤12) are not flagged, and no second-pass sanity check (e.g., consistency with store/receipt corpus year ranges or elimination of implausible dates like month>12 driving fallback)."
    },
    {
      "skill": "image-ocr",
      "defect": "Batch pipeline writes DataFrame directly via pd.ExcelWriter without ensuring None → empty cell; needs explicit per-cell write using openpyxl where None stays as empty cell, or clear instruction to not call astype('object') on a column that may contain real None (which can get coerced). Also needs a step-7 verification: load the written xlsx and assert cells with None are truly empty."
    },
    {
      "skill": "image-ocr",
      "defect": "No voting/consensus across multiple OCR passes. multi_pass_ocr concatenates text, which can create spurious cross-line matches (likely cause for 074.jpg's 702.00 — a cross-line concatenation of digits). Should run extraction per-pass and vote, or deduplicate lines before matching."
    },
    {
      "skill": "image-ocr",
      "defect": "No sanity check on extracted total values: reject implausible values (e.g., >5x any individual item amount if items are extractable; reject numbers without a decimal point when the receipt otherwise uses decimal totals; reject tokens whose character length is inconsistent with surrounding currency formatting)."
    },
    {
      "skill": "image-ocr",
      "defect": "Guidance missing: when a line matched by a priority keyword also contains words like 'INCLUDES', 'INCLUDING', 'EXCLUDES', 'EXCLUDING', 'ROUNDED', 'ROUNDING', treat with care — prefer later lines of same tier."
    },
    {
      "skill": "xlsx",
      "defect": "Does not warn that pandas writing None into an object column via ExcelWriter can produce empty-string-looking cells in some writer versions, nor provide a receipt-friendly pattern for null-preserving writes (e.g., using openpyxl directly with cell.value = None)."
    }
  ],
  "repair_recommendations": [
    {
      "target_skill": "image-ocr",
      "change_type": "edit_total_extraction_logic",
      "generalization": "Applies to any receipt/invoice total extraction task.",
      "specifics": [
        "In extract_total(), after collecting all keyword matches within a tier, prefer the LAST match (bottom-most line) rather than the first, because final payable totals typically appear after subtotals and rounding adjustments.",
        "Within the generic TOTAL/AMOUNT tier, additionally deprioritize lines containing qualifiers in parentheses like '(Inclusive of GST)', '(Excluding GST)', '(Incl GST)', '(Excl GST)', 'TOTAL INCLUDES', when there exists a later plain 'TOTAL:' / 'Total:' line.",
        "Add a secondary preference: if two candidate values differ by a small rounding adjustment (|a-b| < 0.10), prefer the one on the line nearer the bottom (final rounded total)."
      ]
    },
    {
      "target_skill": "image-ocr",
      "change_type": "edit_date_extraction_logic",
      "generalization": "Applies to any receipt OCR task with locale-ambiguous dates.",
      "specifics": [
        "Reorder DATE_PATTERNS to try unambiguous forms first: 'DD MMM YYYY' (textual month) → 'YYYY-MM-DD' / 'YYYY/MM/DD' → 'DD/MM/YYYY' (default for ambiguous slash dates) → 'DD/MM/YY'. Do NOT include '%m-%d-%Y' / '%m/%d/%Y' as fallback; receipts in this corpus are DD/MM.",
        "After parsing, add plausibility checks: year in [2010, 2030]; if both day and month ≤12 and multiple patterns matched, keep the DD/MM/YYYY interpretation (do not swap).",
        "When extracting date, scan the WHOLE page (all OCR passes if used) and collect all candidates; if multiple candidates exist, prefer the one appearing near keywords like 'Date', 'Tarikh', 'Invoice Date', or on a line that also contains a time (HH:MM) — those are usually the transaction date."
      ]
    },
    {
      "target_skill": "image-ocr",
      "change_type": "edit_batch_pipeline_null_handling",
      "generalization": "Applies whenever OCR results populate tabular files with required null-on-failure semantics.",
      "specifics": [
        "Replace pandas-driven write with explicit openpyxl writing in the batch pipeline: create the workbook, name sheet 'results', write header, then for each row assign cell.value = None when the field is None (not empty string, not NaN). This guarantees the Excel cell is truly empty.",
        "Do NOT call .astype('object') or .fillna('') on columns that may contain real None values; keep None as Python None and write via openpyxl.",
        "Add a post-write verification step: reopen the output workbook with openpyxl, iterate all data cells, and assert cell.value is None exactly where extraction failed."
      ]
    },
    {
      "target_skill": "image-ocr",
      "change_type": "add_multi_pass_voting",
      "generalization": "Applies to any batch OCR structured-extraction task with per-image reliability variance.",
      "specifics": [
        "For each image, run 3–4 preprocessing+PSM variants (grayscale+autocontrast ×psm6, sharpen ×psm6, upscaled ×psm4, inverted ×psm6).",
        "Run extract_date() and extract_total() PER PASS, not on concatenated text; collect candidates with their source pass.",
        "Vote: pick the value that appears in the most passes; break ties by preferring passes with higher Tesseract average confidence (image_to_data conf).",
        "Avoid concatenating all passes into one text blob for extraction — this prevents cross-line digit concatenation from producing hallucinated totals (fixes the '702.00'-style failures)."
      ]
    },
    {
      "target_skill": "image-ocr",
      "change_type": "add_total_value_sanity_checks",
      "generalization": "Applies to receipt total extraction.",
      "specifics": [
        "Require the matched number to appear within a plausible currency context: either preceded by 'RM', '$', or followed/preceded by a decimal point, OR be the last column-aligned number on a TOTAL line.",
        "Reject candidates where the integer part has >5 digits unless the receipt text contains a thousand separator pattern.",
        "If the matched total is >10x the median item line amount (when items are parseable), discard and fall back to the next priority tier.",
        "When keyword line has no number and the next line's last token lacks a decimal while all item amounts have decimals, do NOT accept it; look two lines ahead or set to None."
      ]
    },
    {
      "target_skill": "image-ocr",
      "change_type": "expand_exclusion_and_qualifier_lists",
      "generalization": "Applies to any receipt total parsing.",
      "specifics": [
        "Add qualifier-based downgrading (not full exclusion) for lines containing: 'INCLUDES GST', 'INCLUDING GST', 'INCL GST', 'EXCLUDES GST', 'EXCLUDING GST', 'EXCL GST', 'BEFORE ROUNDING', 'TOTAL (INCLUSIVE)', 'TOTAL (EXCLUSIVE)'. These lines may still contain the final amount but prefer a plain 'TOTAL:' line later.",
        "Extend EXCLUSIONS to also skip: 'ROUNDING', 'ROUNDING ADJ', 'ROUNDING ADJUSTMENT', 'SERV. CHARGE', 'SERVICE CHARGE', 'TIP', 'DEPOSIT' when they appear as the SOLE keyword on a line (so a 'Rounded Total' line that contains the final amount is NOT skipped — differentiate 'ROUNDING ADJ' from 'ROUNDED TOTAL')."
      ]
    },
    {
      "target_skill": "xlsx",
      "change_type": "add_null_preservation_guidance",
      "generalization": "Applies to any xlsx output requiring strict null semantics for grading.",
      "specifics": [
        "Add a section 'Preserving Null Cells for Graded Outputs': recommend using openpyxl directly when the grader compares cells with None/empty semantics; show a snippet writing cell.value = None.",
        "Warn against pandas .to_excel() with object columns containing Python None and no explicit na_rep, which can serialize as empty strings in some cases and cause downstream comparisons to fail.",
        "Recommend a verification step: re-open with load_workbook() and inspect cell.value types match expectations (None vs str vs float)."
      ]
    },
    {
      "target_skill": "image-ocr",
      "change_type": "clarify_string_formatting_of_amount",
      "generalization": "Applies to any task requiring amounts as fixed-decimal strings.",
      "specifics": [
        "Reinforce: produce total_amount with exactly two decimals via f\"{v:.2f}\" at extraction time; never store as float in the DataFrame.",
        "When writing via openpyxl, set cell.number_format = '@' (text) for the total_amount column to prevent Excel from reinterpreting '20.00' as the number 20 and losing the trailing zero on display or re-read."
      ]
    }
  ],
  "confidence": {
    "overall": 0.72,
    "notes": "Four field-level errors are confirmed by field_feedback (034 date, 074/077/078 amount). Hypotheses for root causes are reasoned from receipt content and the current skill text; the exact code path that produced each failure is not directly observable from the window, so some recommendations (especially the None→'' coercion for 078) are the most-likely explanation among plausible alternatives rather than proven. The priority-last-vs-first fix for 077 is high-confidence (0.9) given 'Total (Inclusive of GST): 23.26' precedes 'TOTAL: 23.25'. The DD/MM date fix is high-confidence (0.85). The 074 '702.00' hallucination fix (per-pass extraction + sanity checks) is moderate-confidence (0.6)."
  }
}
